const dados = $json.output ?? $json;

if (['Etanol', 'álcool', 'alcool'].includes(dados.combustivel)) {
  dados.combustivel = 'etanol';
}

const camposObrigatorios = [
  {
    campo: 'data',
    pergunta: 'Qual foi a data do abastecimento?'
  },
  {
    campo: 'veiculo_id',
    pergunta: 'Qual foi o veículo?'
  },
  {
    campo: 'combustivel',
    pergunta: 'Qual foi o combustível?'
  },
  {
    campo: 'litros',
    pergunta: 'Quantos litros foram abastecidos?'
  },
  {
    campo: 'valor_total',
    pergunta: 'Qual foi o valor total?'
  },
  {
    campo: 'odometro',
    pergunta: 'Qual é a quilometragem atual do veículo?'
  }
];

function estaAusente(valor) {
  return (
    valor === null ||
    valor === undefined ||
    (typeof valor === 'string' && valor.trim() === '')
  );
}

const camposFaltantes = camposObrigatorios.filter(
  item => estaAusente(dados[item.campo])
);

const proximoCampo = camposFaltantes[0] ?? null;

return {
  json: {
    ...dados,
    campos_faltantes: camposFaltantes.map(item => item.campo),
    dados_completos: camposFaltantes.length === 0,
    proximo_campo: proximoCampo?.campo ?? null,
    pergunta: proximoCampo?.pergunta ?? null
  }
};

