parameters.jsCode:
const pendencia = $('Buscar pendencia').item.json;

if (pendencia.status !== 'aguardando_confirmacao') {
  throw new Error(
    'Não existe um abastecimento aguardando confirmação.'
  );
}

if (!pendencia.dados_json) {
  throw new Error(
    'A pendência não possui dados para confirmar.'
  );
}

let dados;

try {
  dados = JSON.parse(pendencia.dados_json);
} catch (error) {
  throw new Error(
    `Não foi possível interpretar os dados pendentes: ${error.message}`
  );
}

return {
  json: {
    output: {
      data: dados.data,
      veiculo_id: dados.veiculo_id,
      combustivel: dados.combustivel,
      litros: dados.litros,
      valor_total: dados.valor_total,
      odometro: dados.odometro,
      observacao: dados.observacao
    }
  }
};
